const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, Header, Footer, PageNumber
} = require('docx');
const fs = require('fs');

const BRAND_PURPLE = "4B2C6E";
const BRAND_LIGHT = "F3EEF9";
const BRAND_GOLD = "C9A84C";
const GRAY_LIGHT = "F5F5F5";
const GRAY_MID = "E0E0E0";
const WHITE = "FFFFFF";

const border = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 360, after: 160 },
    children: [new TextRun({ text, font: "Arial", size: 32, bold: true, color: BRAND_PURPLE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 280, after: 120 },
    children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color: BRAND_PURPLE })]
  });
}

function h3(text) {
  return new Paragraph({
    spacing: { before: 200, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: BRAND_GOLD })]
  });
}

function body(text, bold = false, italic = false) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 20, bold, italic })]
  });
}

function bullet(text, bold = false) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 40, after: 40 },
    children: [new TextRun({ text, font: "Arial", size: 20, bold })]
  });
}

function subbullet(text) {
  return new Paragraph({
    numbering: { reference: "subbullets", level: 0 },
    spacing: { before: 30, after: 30 },
    children: [new TextRun({ text, font: "Arial", size: 19, color: "444444" })]
  });
}

function space(sz = 80) {
  return new Paragraph({ spacing: { before: sz, after: sz }, children: [new TextRun("")] });
}

function divider() {
  return new Paragraph({
    spacing: { before: 120, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: BRAND_PURPLE, space: 1 } },
    children: [new TextRun("")]
  });
}

function labeledPara(label, text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [
      new TextRun({ text: label + ": ", font: "Arial", size: 20, bold: true, color: BRAND_PURPLE }),
      new TextRun({ text, font: "Arial", size: 20 })
    ]
  });
}

function shadeBox(items, fillColor = BRAND_LIGHT) {
  const rows = items.map(item =>
    new TableRow({
      children: [
        new TableCell({
          borders: noBorders,
          width: { size: 9360, type: WidthType.DXA },
          shading: { fill: fillColor, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 180, right: 180 },
          children: typeof item === "string"
            ? [new Paragraph({ children: [new TextRun({ text: item, font: "Arial", size: 20 })] })]
            : [item]
        })
      ]
    })
  );
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows
  });
}

function assignmentTable(rows) {
  const headerRow = new TableRow({
    children: [
      new TableCell({
        borders, width: { size: 2200, type: WidthType.DXA },
        shading: { fill: BRAND_PURPLE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Who", font: "Arial", size: 20, bold: true, color: WHITE })] })]
      }),
      new TableCell({
        borders, width: { size: 2400, type: WidthType.DXA },
        shading: { fill: BRAND_PURPLE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Task", font: "Arial", size: 20, bold: true, color: WHITE })] })]
      }),
      new TableCell({
        borders, width: { size: 4760, type: WidthType.DXA },
        shading: { fill: BRAND_PURPLE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Specific Example / Deliverable", font: "Arial", size: 20, bold: true, color: WHITE })] })]
      })
    ]
  });

  const dataRows = rows.map((r, i) =>
    new TableRow({
      children: [
        new TableCell({
          borders, width: { size: 2200, type: WidthType.DXA },
          shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: r[0], font: "Arial", size: 19, bold: true, color: BRAND_PURPLE })] })]
        }),
        new TableCell({
          borders, width: { size: 2400, type: WidthType.DXA },
          shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: r[1], font: "Arial", size: 19 })] })]
        }),
        new TableCell({
          borders, width: { size: 4760, type: WidthType.DXA },
          shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: r[2], font: "Arial", size: 19 })] })]
        })
      ]
    })
  );

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2200, 2400, 4760],
    rows: [headerRow, ...dataRows]
  });
}

function weeklyTable(days) {
  const headerRow = new TableRow({
    children: [
      new TableCell({
        borders, width: { size: 1400, type: WidthType.DXA },
        shading: { fill: BRAND_PURPLE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Day", font: "Arial", size: 20, bold: true, color: WHITE })] })]
      }),
      new TableCell({
        borders, width: { size: 2500, type: WidthType.DXA },
        shading: { fill: BRAND_PURPLE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Content Type", font: "Arial", size: 20, bold: true, color: WHITE })] })]
      }),
      new TableCell({
        borders, width: { size: 3000, type: WidthType.DXA },
        shading: { fill: BRAND_PURPLE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Example Post / Hook", font: "Arial", size: 20, bold: true, color: WHITE })] })]
      }),
      new TableCell({
        borders, width: { size: 2460, type: WidthType.DXA },
        shading: { fill: BRAND_PURPLE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Owner", font: "Arial", size: 20, bold: true, color: WHITE })] })]
      })
    ]
  });

  const dataRows = days.map((d, i) =>
    new TableRow({
      children: [
        new TableCell({
          borders, width: { size: 1400, type: WidthType.DXA },
          shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: d[0], font: "Arial", size: 19, bold: true })] })]
        }),
        new TableCell({
          borders, width: { size: 2500, type: WidthType.DXA },
          shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: d[1], font: "Arial", size: 19 })] })]
        }),
        new TableCell({
          borders, width: { size: 3000, type: WidthType.DXA },
          shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: d[2], font: "Arial", size: 19 })] })]
        }),
        new TableCell({
          borders, width: { size: 2460, type: WidthType.DXA },
          shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: d[3], font: "Arial", size: 19, bold: true, color: BRAND_PURPLE })] })]
        })
      ]
    })
  );

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [1400, 2500, 3000, 2460],
    rows: [headerRow, ...dataRows]
  });
}

function adTable(rows) {
  const headerRow = new TableRow({
    children: ["Ad Name", "Objective", "Hook / Copy", "CTA", "Owner"].map(h =>
      new TableCell({
        borders, width: { size: 1872, type: WidthType.DXA },
        shading: { fill: BRAND_PURPLE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 100, right: 100 },
        children: [new Paragraph({ children: [new TextRun({ text: h, font: "Arial", size: 19, bold: true, color: WHITE })] })]
      })
    )
  });
  const dataRows = rows.map((r, i) =>
    new TableRow({
      children: r.map(cell =>
        new TableCell({
          borders, width: { size: 1872, type: WidthType.DXA },
          shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 100, right: 100 },
          children: [new Paragraph({ children: [new TextRun({ text: cell, font: "Arial", size: 18 })] })]
        })
      )
    })
  );
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [1872, 1872, 1872, 1872, 1872],
    rows: [headerRow, ...dataRows]
  });
}

