                margins: { top: 80, bottom: 80, left: 120, right: 120 },
                children: [new Paragraph({ children: [new TextRun({ text: h, font: "Arial", size: 20, bold: true, color: WHITE })] })]
              })
            )
          }),
          ...([
            ["Organic content posts published", "5 per week", "Southern Social"],
            ["Short-form Reels posted", "2 per week", "Bethany + Southern Social"],
            ["Ad impressions (cold traffic)", "5,000 to 10,000/week", "Jacques"],
            ["Cost per lead (Market Blueprint apply)", "Under $40", "Jacques"],
            ["New DM conversations opened", "10 to 20 per week", "Aanchal"],
            ["Market Blueprint calls booked", "4 to 6 per week", "Aanchal + Eric"],
            ["Email open rate", "35% or higher", "Aanchal"],
            ["Calls to close rate", "25% or higher", "Bethany"]
          ].map((r, i) =>
            new TableRow({
              children: r.map(cell =>
                new TableCell({
                  borders, width: { size: 3120, type: WidthType.DXA },
                  shading: { fill: i % 2 === 0 ? GRAY_LIGHT : WHITE, type: ShadingType.CLEAR },
                  margins: { top: 80, bottom: 80, left: 120, right: 120 },
                  children: [new Paragraph({ children: [new TextRun({ text: cell, font: "Arial", size: 19 })] })]
                })
              )
            })
          ))
        ]
      }),
      space(80),
      divider(),

      // ══════════ FINAL NOTE ══════════
      h1("FINAL NOTE FROM BETHANY"),
      body("The reason this works is because it is true. You lived this industry. You know what these owners are carrying. Every piece of content should come from that place."),
      space(40),
      body("The goal is not to sound like a consultant. The goal is to sound like the person who has been exactly where they are and actually found the way through."),
      space(40),
      body("When you get that right, the funnel is not a funnel. It is a community. And that is what RichQueen built. That is what Luxora is building too."),
      space(80),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 120, after: 120 },
        children: [new TextRun({ text: "The Luxora Collective | theluxoracollective.co", font: "Arial", size: 18, italic: true, color: "888888" })]
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_Female_Funnel_Action_Plan.docx", buffer);
  console.log("Done.");
});
