const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

// ─── COLORS ─────────────────────────────────────────────────────────────────
const PURPLE     = "4B2C6E";
const PURPLE_MID = "7B5EA7";
const GOLD       = "C9A84C";
const LIGHT_PURPLE = "F0EAF8";
const LIGHT_GOLD   = "FDF6E3";
const GRAY       = "F5F5F5";
const GRAY_MID   = "E8E8E8";
const WHITE      = "FFFFFF";
const DARK       = "222222";
const MID_TEXT   = "555555";

// ─── BORDERS ────────────────────────────────────────────────────────────────
const b = (c = "CCCCCC") => ({ style: BorderStyle.SINGLE, size: 1, color: c });
const borders = { top: b(), bottom: b(), left: b(), right: b() };
const purpleBorders = { top: b(PURPLE), bottom: b(PURPLE), left: b(PURPLE), right: b(PURPLE) };
const noBorder = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

// ─── HELPERS ────────────────────────────────────────────────────────────────
const sp = (n = 60) => new Paragraph({ spacing: { before: n, after: n }, children: [new TextRun("")] });

const div = (color = PURPLE) => new Paragraph({
  spacing: { before: 120, after: 120 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color, space: 1 } },
  children: [new TextRun("")]
});

const pageBreak = () => new Paragraph({ children: [new PageBreak()] });

const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 320, after: 140 },
  children: [new TextRun({ text, font: "Arial", size: 34, bold: true, color: PURPLE })]
});

const h2 = (text, color = PURPLE) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 240, after: 100 },
  children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color })]
});

const h3 = (text) => new Paragraph({
  spacing: { before: 180, after: 80 },
  children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: GOLD })]
});

const body = (text, opts = {}) => new Paragraph({
  spacing: { before: 60, after: 60 },
  children: [new TextRun({ text, font: "Arial", size: 20, color: DARK, ...opts })]
});

const caption = (text) => new Paragraph({
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text, font: "Arial", size: 18, italic: true, color: MID_TEXT })]
});

const bul = (text, bold = false) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text, font: "Arial", size: 20, bold, color: DARK })]
});

const num = (text) => new Paragraph({
  numbering: { reference: "numbers", level: 0 },
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text, font: "Arial", size: 20, color: DARK })]
});

const tag = (label, text) => new Paragraph({
  spacing: { before: 60, after: 60 },
  children: [
    new TextRun({ text: label + ": ", font: "Arial", size: 20, bold: true, color: PURPLE }),
    new TextRun({ text, font: "Arial", size: 20, color: DARK })
  ]
});

// Callout box
const box = (lines, fill = LIGHT_PURPLE, textColor = DARK) => {
  const cells = lines.map(line => {
    const isEmpty = line.trim() === "";
    return new TableRow({
      children: [new TableCell({
        borders: noBorders,
        width: { size: 9000, type: WidthType.DXA },
        shading: { fill, type: ShadingType.CLEAR },
        margins: { top: 60, bottom: 60, left: 200, right: 200 },
        children: [new Paragraph({
          spacing: { before: isEmpty ? 30 : 40, after: isEmpty ? 30 : 40 },
          children: [new TextRun({ text: line, font: "Arial", size: isEmpty ? 10 : 19, color: textColor })]
        })]
      })]
    });
  });
  return new Table({ width: { size: 9000, type: WidthType.DXA }, columnWidths: [9000], rows: cells });
};

// Standard 3-col assignment table
const aTable = (rows) => {
  const hRow = new TableRow({ children: [
    mkH("Who", 1800), mkH("Action", 2800), mkH("Specific Deliverable / Example", 4400)
  ]});
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [1800, 2800, 4400],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 1800, i, true), mkC(r[1], 2800, i), mkC(r[2], 4400, i)
    ]}))]
  });
};

// 2-col comparison table
const cTable = (leftHead, rightHead, rows) => {
  const hRow = new TableRow({ children: [mkH(leftHead, 4500), mkH(rightHead, 4500)] });
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [4500, 4500],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 4500, i), mkC(r[1], 4500, i)
    ]}))]
  });
};

// Timeline table
const timelineTable = (rows) => {
  const hRow = new TableRow({ children: [
    mkH("Phase / Timeline", 1600), mkH("Goal", 2000), mkH("Actions", 2800), mkH("Owner", 2400)
  ]});
  return new Table({
    width: { size: 8800, type: WidthType.DXA },
    columnWidths: [1600, 2000, 2800, 2400],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 1600, i, true, PURPLE), mkC(r[1], 2000, i), mkC(r[2], 2800, i), mkC(r[3], 2400, i, true, PURPLE_MID)
    ]}))]
  });
};

// Ad table
const adTable = (rows) => {
  const hRow = new TableRow({ children: [
    mkH("Ad Name", 1500), mkH("Hook (First Line)", 2800), mkH("Body Copy Direction", 2800), mkH("CTA", 1900)
  ]});
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [1500, 2800, 2800, 1900],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 1500, i, true), mkC(r[1], 2800, i), mkC(r[2], 2800, i), mkC(r[3], 1900, i)
    ]}))]
  });
};

// Offer ladder table
const offerTable = (rows) => {
  const hRow = new TableRow({ children: [
    mkH("Tier", 1400), mkH("Offer Name", 2200), mkH("Price", 1000), mkH("Who It Is For", 2000), mkH("Status", 2400)
  ]});
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [1400, 2200, 1000, 2000, 2400],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 1400, i, true, PURPLE), mkC(r[1], 2200, i, true), mkC(r[2], 1000, i), mkC(r[3], 2000, i), mkC(r[4], 2400, i)
    ]}))]
  });
};

// Weekly content calendar
const weekTable = (rows) => {
  const hRow = new TableRow({ children: [
    mkH("Day", 1000), mkH("Content Type", 1800), mkH("Example Hook or Post", 3000), mkH("Owner", 1600), mkH("Format", 1600)
  ]});
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [1000, 1800, 3000, 1600, 1600],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 1000, i, true, PURPLE), mkC(r[1], 1800, i, true), mkC(r[2], 3000, i), mkC(r[3], 1600, i, true, PURPLE_MID), mkC(r[4], 1600, i)
    ]}))]
  });
};

function mkH(text, w) {
  return new TableCell({
    borders: purpleBorders, width: { size: w, type: WidthType.DXA },
    shading: { fill: PURPLE, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({ children: [new TextRun({ text, font: "Arial", size: 19, bold: true, color: WHITE })] })]
  });
}

function mkC(text, w, i, bold = false, color = DARK) {
  return new TableCell({
    borders, width: { size: w, type: WidthType.DXA },
    shading: { fill: i % 2 === 0 ? GRAY : WHITE, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({ children: [new TextRun({ text, font: "Arial", size: 18, bold, color })] })]
  });
}

// ─── DOCUMENT ───────────────────────────────────────────────────────────────
const doc = new Document({
  numbering: {
    config: [
      { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
      { reference: "numbers", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] }
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 20 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 34, bold: true, font: "Arial", color: PURPLE }, paragraph: { spacing: { before: 320, after: 140 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 26, bold: true, font: "Arial", color: PURPLE }, paragraph: { spacing: { before: 240, after: 100 }, outlineLevel: 1 } }
    ]
  },
  sections: [{
    properties: {
      page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1260, bottom: 1260, left: 1260 } }
    },
    children: [

      // ══════════════════════════════════════════════
      // COVER PAGE
      // ══════════════════════════════════════════════
      sp(400),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 160 }, children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 52, bold: true, color: PURPLE })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 120 }, children: [new TextRun({ text: "The Feminine Funnel Growth Playbook", font: "Arial", size: 34, bold: true, color: GOLD })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: "A Full Team Action Plan for Building a $1M/Month Brand", font: "Arial", size: 22, italic: true, color: MID_TEXT })] }),
      sp(40),
      div(GOLD),
      sp(40),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "Inspired by: RichQueen (Leanne Lopez Mosley) + Shoshanna Raven", font: "Arial", size: 20, color: PURPLE_MID })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "Built for: The Luxora Collective | theluxoracollective.co", font: "Arial", size: 20, color: MID_TEXT })] }),
      sp(60),
      box([
        "HOW TO USE THIS DOCUMENT",
        " ",
        "Bethany: Read this the night before your team meeting. There are presenter notes in italics throughout. The document is designed to be walked through in 60 minutes.",
        " ",
        "Team Members: Your name appears next to every action item assigned to you. If you see your name, that is your lane. Stay in it and execute.",
        " ",
        "Eric: You own the execution calendar. Your job is to make sure this document does not become a shelf document."
      ], LIGHT_PURPLE),
      sp(60),

      // ── MEETING GUIDE BOX ─────────────────────────
      box([
        "MEETING GUIDE: 60-MINUTE AGENDA",
        " ",
        "0:00 to 0:05   Welcome and why this matters (Bethany)",
        "0:05 to 0:15   Section 1: The Two Women We Are Learning From",
        "0:15 to 0:30   Section 2: The Luxora Feminine Funnel (our version)",
        "0:30 to 0:40   Section 3: What We Change Right Now (ads, content, messaging)",
        "0:40 to 0:52   Section 4: The Build Timeline (Month 1 through Month 12)",
        "0:52 to 1:00   Section 5: Team Assignments + Q&A"
      ], LIGHT_GOLD, DARK),
      sp(80),

      // ══════════════════════════════════════════════
      // SECTION 1: THE TWO WOMEN
      // ══════════════════════════════════════════════
      pageBreak(),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: "SECTION 1", font: "Arial", size: 22, bold: true, color: GOLD })] }),
      h1("The Two Women We Are Learning From"),
      body("Before we talk about Luxora, we need to understand what these two women built and why it works. We are not copying them. We are extracting the mechanics and rebuilding them in a way that is native to Luxora, our audience, and Bethany's story."),
      sp(40),
      caption("PRESENTER NOTE: Use this section to frame the conversation. These are not competitors. They are benchmarks. We are studying what a $1M/month brand looks like so we can build our version of it."),
      sp(60),
      div(),

      h2("RichQueen: Leanne Lopez Mosley"),
      body("Leanne built her brand around one core insight: women do not buy from pressure. They buy when they feel safe, seen, and certain that the outcome is already theirs. Her entire system is built to remove friction before the sale ever happens."),
      sp(40),
      h3("What She Actually Does"),
      bul("She builds trust across six layers simultaneously before making any offer: authority proof, relatability proof, consistency proof, social proof, thought leadership, and identity alignment."),
      bul("Her content does not describe her offer. It describes her buyer. The woman reading feels like the content was written for her specifically."),
      bul("She uses a soft conversion model: no urgency pressure, no aggressive CTAs. Her calls to action sound like invitations, not deadlines."),
      bul("She shows up every single day with the same core message in different formats. Repetition builds belief. Belief precedes purchase."),
      sp(40),
      h3("The Mechanic Luxora Steals"),
      box([
        "Trust Stacking: Stack proof from six different angles so that by the time a prospect gets on a call, she has already decided. The call is just confirmation.",
        " ",
        "Soft Conversion Language: Replace 'Book now' with 'If you are ready...' Replace 'Limited spots' with 'Here is how to work with us.' The buyer should feel like she is choosing, not being closed."
      ], LIGHT_PURPLE),
      sp(60),
      div(),

      h2("Shoshanna Raven: Living Brave"),
      body("Shoshanna built a $3M+ business without selling a service. She sold a movement. Her buyers do not think of themselves as clients. They think of themselves as brave women who chose to level up. That identity lock-in is worth more than any sales script."),
      sp(40),
      h3("What She Actually Does"),
      bul("She runs a three-tier ascension model: low-barrier entry ($30 to $99), mid-funnel live events, and a high-ticket mastermind ($19K to $33K/year called The Vortex)."),
      bul("She generated $3.7M in 10 days from a single event funnel. She leads with education and emotion, then makes one clear high-ticket offer at the peak of the event."),
      bul("She monetizes proximity, not information. Her buyers pay to be in her world and in the room with other high-level women. The content is almost secondary."),
      bul("She built a category phrase: 'Living Brave.' Every piece of content orbits that phrase. It gives her audience an identity to claim."),
      sp(40),
      h3("The Mechanic Luxora Steals"),
      box([
        "Ascension Funnel: Never go from cold to high-ticket in one step. Build rungs on the ladder. Low ticket creates volume. Volume creates warmth. Warmth creates conversion.",
        " ",
        "Event as a Revenue Spike: One quarterly virtual event can generate as much pipeline as three months of ads. When Bethany teaches live, close rates skyrocket.",
        " ",
        "Category of One Phrase: Luxora needs a phrase that people repeat. When your audience uses your language, you have won."
      ], LIGHT_PURPLE),
      sp(60),
      div(),

      h2("Why Luxora Is Different (And Why That Is an Advantage)"),
      body("Both of these women sell B2C: to individual women buying transformation for themselves. Luxora sells B2B: to med spa owners buying growth systems for their clinics. The emotional mechanics are identical. The language and proof have to shift."),
      sp(40),
      cTable(
        "RichQueen / Shoshanna (B2C)",
        "Luxora (B2B, Med Spa)",
        [
          ["'Are you brave enough to invest in yourself?'", "'Are you ready to stop running your business on guesswork?'"],
          ["Sells: personal identity transformation", "Sells: professional outcome + owner freedom"],
          ["Buyer is investing in herself", "Buyer is investing in her business (and by extension, herself)"],
          ["Proof: personal revenue growth, mindset shifts", "Proof: clinic revenue growth, show rate improvements, retained clients"],
          ["Community: women in personal development", "Community: med spa owners who run real businesses"]
        ]
      ),
      sp(40),
      body("Bethany's advantage: she has lived both sides. She ran a med spa. She built a consultancy. She rebuilt after a hard season. No other consultancy in this space has that story and that operator credibility simultaneously."),
      sp(80),

      // ══════════════════════════════════════════════
      // SECTION 2: THE LUXORA FEMININE FUNNEL
      // ══════════════════════════════════════════════
      pageBreak(),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: "SECTION 2", font: "Arial", size: 22, bold: true, color: GOLD })] }),
      h1("The Luxora Feminine Funnel"),
      body("This is not a traditional marketing funnel. It is a trust ecosystem. Every piece of content, every ad, every email, and every conversation works together to make the sale feel like the obvious next step rather than a decision."),
      sp(40),
      caption("PRESENTER NOTE: Draw this on a whiteboard if you have one. Walk the team through it visually. Cold stranger at the top, retained Elite client at the bottom. Show how each team member owns a layer."),
      sp(60),

      box([
        "THE LUXORA FUNNEL FLOW",
        " ",
        "COLD STRANGER",
        "  Sees a Reel, Truth Bomb post, or cold Meta ad",
        "  Feels: 'This is about me. She gets it.'",
        " ",
        "WARM FOLLOWER",
        "  Follows Luxora. Watches content. Sees proof repeatedly.",
        "  Feels: 'I trust her. She knows this space.'",
        " ",
        "ENGAGED PROSPECT",
        "  Downloads a free resource, purchases the low-ticket Playbook, or responds to a DM",
        "  Feels: 'This is exactly what I needed.'",
        " ",
        "QUALIFIED LEAD",
        "  Applies for or books a Market Blueprint call",
        "  Feels: 'I am ready. I just need to confirm this is right.'",
        " ",
        "CLIENT",
        "  Enrolls in the 90-Day Growth Engine",
        "  Feels: 'This is the best investment I have made in this business.'",
        " ",
        "ELITE CLIENT (Future)",
        "  Joins Luxora Elite mastermind",
        "  Feels: 'I am part of something. This is my standard now.'"
      ], LIGHT_PURPLE),
      sp(60),
      div(),

      h2("The Full Offer Ladder"),
      body("Every tier exists for a reason. Low ticket warms leads and funds ad spend. The Blueprint call closes the core offer. Elite creates recurring high-margin revenue. This is the Shoshanna ascension model adapted for B2B med spa."),
      sp(40),
