const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

// ─── COLORS ─────────────────────────────────────────────────────────────────
const PURPLE     = "4B2C6E";
const PURPLE_MID = "7B5EA7";
const GOLD       = "C9A84C";
const LIGHT_PURPLE = "F0EAF8";
const LIGHT_GOLD   = "FDF6E3";
const GRAY       = "F5F5F5";
const GRAY_MID   = "E8E8E8";
const WHITE      = "FFFFFF";
const DARK       = "222222";
const MID_TEXT   = "555555";

// ─── BORDERS ────────────────────────────────────────────────────────────────
const b = (c = "CCCCCC") => ({ style: BorderStyle.SINGLE, size: 1, color: c });
const borders = { top: b(), bottom: b(), left: b(), right: b() };
const purpleBorders = { top: b(PURPLE), bottom: b(PURPLE), left: b(PURPLE), right: b(PURPLE) };
const noBorder = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

// ─── HELPERS ────────────────────────────────────────────────────────────────
const sp = (n = 60) => new Paragraph({ spacing: { before: n, after: n }, children: [new TextRun("")] });

const div = (color = PURPLE) => new Paragraph({
  spacing: { before: 120, after: 120 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color, space: 1 } },
  children: [new TextRun("")]
});

const pageBreak = () => new Paragraph({ children: [new PageBreak()] });

const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 320, after: 140 },
  children: [new TextRun({ text, font: "Arial", size: 34, bold: true, color: PURPLE })]
});

const h2 = (text, color = PURPLE) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 240, after: 100 },
  children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color })]
});

const h3 = (text) => new Paragraph({
  spacing: { before: 180, after: 80 },
  children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: GOLD })]
});

const body = (text, opts = {}) => new Paragraph({
  spacing: { before: 60, after: 60 },
  children: [new TextRun({ text, font: "Arial", size: 20, color: DARK, ...opts })]
});

const caption = (text) => new Paragraph({
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text, font: "Arial", size: 18, italic: true, color: MID_TEXT })]
});

const bul = (text, bold = false) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text, font: "Arial", size: 20, bold, color: DARK })]
});

const num = (text) => new Paragraph({
  numbering: { reference: "numbers", level: 0 },
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text, font: "Arial", size: 20, color: DARK })]
});

const tag = (label, text) => new Paragraph({
  spacing: { before: 60, after: 60 },
  children: [
    new TextRun({ text: label + ": ", font: "Arial", size: 20, bold: true, color: PURPLE }),
    new TextRun({ text, font: "Arial", size: 20, color: DARK })
  ]
});

// Callout box
const box = (lines, fill = LIGHT_PURPLE, textColor = DARK) => {
  const cells = lines.map(line => {
    const isEmpty = line.trim() === "";
    return new TableRow({
      children: [new TableCell({
        borders: noBorders,
        width: { size: 9000, type: WidthType.DXA },
        shading: { fill, type: ShadingType.CLEAR },
        margins: { top: 60, bottom: 60, left: 200, right: 200 },
        children: [new Paragraph({
          spacing: { before: isEmpty ? 30 : 40, after: isEmpty ? 30 : 40 },
          children: [new TextRun({ text: line, font: "Arial", size: isEmpty ? 10 : 19, color: textColor })]
        })]
      })]
    });
  });
  return new Table({ width: { size: 9000, type: WidthType.DXA }, columnWidths: [9000], rows: cells });
};

// Standard 3-col assignment table
const aTable = (rows) => {
  const hRow = new TableRow({ children: [
    mkH("Who", 1800), mkH("Action", 2800), mkH("Specific Deliverable / Example", 4400)
  ]});
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [1800, 2800, 4400],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 1800, i, true), mkC(r[1], 2800, i), mkC(r[2], 4400, i)
    ]}))]
  });
};

// 2-col comparison table
const cTable = (leftHead, rightHead, rows) => {
  const hRow = new TableRow({ children: [mkH(leftHead, 4500), mkH(rightHead, 4500)] });
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [4500, 4500],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 4500, i), mkC(r[1], 4500, i)
    ]}))]
  });
};

// Timeline table
const timelineTable = (rows) => {
