      mkC(r[0], 1500, i, true), mkC(r[1], 2800, i), mkC(r[2], 2800, i), mkC(r[3], 1900, i)
    ]}))]
  });
};

// Offer ladder table
const offerTable = (rows) => {
  const hRow = new TableRow({ children: [
    mkH("Tier", 1400), mkH("Offer Name", 2200), mkH("Price", 1000), mkH("Who It Is For", 2000), mkH("Status", 2400)
  ]});
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [1400, 2200, 1000, 2000, 2400],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 1400, i, true, PURPLE), mkC(r[1], 2200, i, true), mkC(r[2], 1000, i), mkC(r[3], 2000, i), mkC(r[4], 2400, i)
    ]}))]
  });
};

// Weekly content calendar
const weekTable = (rows) => {
  const hRow = new TableRow({ children: [
    mkH("Day", 1000), mkH("Content Type", 1800), mkH("Example Hook or Post", 3000), mkH("Owner", 1600), mkH("Format", 1600)
  ]});
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: [1000, 1800, 3000, 1600, 1600],
    rows: [hRow, ...rows.map((r, i) => new TableRow({ children: [
      mkC(r[0], 1000, i, true, PURPLE), mkC(r[1], 1800, i, true), mkC(r[2], 3000, i), mkC(r[3], 1600, i, true, PURPLE_MID), mkC(r[4], 1600, i)
    ]}))]
  });
};

function mkH(text, w) {
  return new TableCell({
    borders: purpleBorders, width: { size: w, type: WidthType.DXA },
    shading: { fill: PURPLE, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({ children: [new TextRun({ text, font: "Arial", size: 19, bold: true, color: WHITE })] })]
  });
}

function mkC(text, w, i, bold = false, color = DARK) {
  return new TableCell({
    borders, width: { size: w, type: WidthType.DXA },
    shading: { fill: i % 2 === 0 ? GRAY : WHITE, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({ children: [new TextRun({ text, font: "Arial", size: 18, bold, color })] })]
  });
}

// ─── DOCUMENT ───────────────────────────────────────────────────────────────
const doc = new Document({
  numbering: {
