      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 40 }, children: [new TextRun({ text: "Bethany | Co-Founder and CEO", font: "Arial", size: 18, color: MID_TEXT })] }),

    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_Feminine_Funnel_Playbook.docx", buffer);
  console.log("Done.");
});

