const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

// ─── COLORS ─────────────────────────────────────────────────────────────────
const PURPLE      = "3D1F6E";
const PURPLE_MID  = "6B4DAA";
const PURPLE_SOFT = "9B7FCC";
const GOLD        = "B8922A";
const GOLD_LIGHT  = "E8C96A";
const CREAM       = "FBF8F2";
const LIGHT_PUR   = "EDE5F7";
const LIGHT_GOLD  = "FDF6E3";
const GRAY        = "F4F4F4";
const WHITE       = "FFFFFF";
const DARK        = "1A1A1A";
const MID         = "555555";

// ─── BORDERS ────────────────────────────────────────────────────────────────
const nb = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: nb, bottom: nb, left: nb, right: nb };
const tb = (c = "CCCCCC") => ({ style: BorderStyle.SINGLE, size: 1, color: c });
const borders = { top: tb(), bottom: tb(), left: tb(), right: tb() };
const purpB = { top: tb(PURPLE), bottom: tb(PURPLE), left: tb(PURPLE), right: tb(PURPLE) };

// ─── PRIMITIVES ──────────────────────────────────────────────────────────────
const sp = (n = 60) => new Paragraph({ spacing: { before: n, after: n }, children: [new TextRun("")] });
const pb = () => new Paragraph({ children: [new PageBreak()] });

const div = (c = PURPLE) => new Paragraph({
  spacing: { before: 100, after: 100 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: c, space: 1 } },
  children: [new TextRun("")]
});

const thin = () => new Paragraph({
  spacing: { before: 60, after: 60 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD", space: 1 } },
  children: [new TextRun("")]
});

const h1 = (t) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 300, after: 120 },
  children: [new TextRun({ text: t, font: "Arial", size: 36, bold: true, color: PURPLE })]
});

const h2 = (t, c = PURPLE) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 220, after: 100 },
  children: [new TextRun({ text: t, font: "Arial", size: 26, bold: true, color: c })]
});

const h3 = (t) => new Paragraph({
  spacing: { before: 160, after: 70 },
  children: [new TextRun({ text: t, font: "Arial", size: 22, bold: true, color: GOLD })]
});

const body = (t, bold = false, color = DARK) => new Paragraph({
  spacing: { before: 55, after: 55 },
  children: [new TextRun({ text: t, font: "Arial", size: 20, bold, color })]
});

const italic = (t, c = MID) => new Paragraph({
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text: t, font: "Arial", size: 18, italic: true, color: c })]
});

const bul = (t, bold = false) => new Paragraph({
  numbering: { reference: "bul", level: 0 },
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text: t, font: "Arial", size: 20, bold, color: DARK })]
});

const tagged = (label, t, labelColor = PURPLE) => new Paragraph({
  spacing: { before: 60, after: 60 },
  children: [
    new TextRun({ text: label + ": ", font: "Arial", size: 20, bold: true, color: labelColor }),
    new TextRun({ text: t, font: "Arial", size: 20, color: DARK })
  ]
});

// ─── BOX ────────────────────────────────────────────────────────────────────
const box = (lines, fill = LIGHT_PUR, textColor = DARK, bold = false) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [9000],
  rows: lines.map(line => new TableRow({ children: [new TableCell({
    borders: noBorders,
    width: { size: 9000, type: WidthType.DXA },
    shading: { fill, type: ShadingType.CLEAR },
    margins: { top: 70, bottom: 70, left: 220, right: 220 },
    children: [new Paragraph({
      spacing: { before: line.trim() === "" ? 20 : 40, after: line.trim() === "" ? 20 : 40 },
      children: [new TextRun({ text: line, font: "Arial", size: line.trim() === "" ? 8 : 19, color: textColor, bold: bold && line.trim() !== "" && !line.startsWith("  ") })]
    })]
  })]})
)});

// ─── SECTION HEADER ─────────────────────────────────────────────────────────
const sectionLabel = (n, t) => [
  sp(20),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: n, font: "Arial", size: 20, bold: true, color: GOLD })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: t, font: "Arial", size: 32, bold: true, color: PURPLE })] }),
  div(),
  sp(20)
];

// ─── TABLES ─────────────────────────────────────────────────────────────────
function mkH(t, w) {
  return new TableCell({ borders: purpB, width: { size: w, type: WidthType.DXA }, shading: { fill: PURPLE, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 130, right: 130 }, children: [new Paragraph({ children: [new TextRun({ text: t, font: "Arial", size: 19, bold: true, color: WHITE })] })] });
}
function mkC(t, w, i, bold = false, c = DARK) {
  return new TableCell({ borders, width: { size: w, type: WidthType.DXA }, shading: { fill: i % 2 === 0 ? GRAY : WHITE, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 130, right: 130 }, children: [new Paragraph({ children: [new TextRun({ text: t, font: "Arial", size: 18, bold, color: c })] })] });
}

const adTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [1600, 2600, 2800, 2000],
  rows: [
    new TableRow({ children: [mkH("Ad Name", 1600), mkH("Hook / Opening Line", 2600), mkH("Body Direction + Emotion", 2800), mkH("CTA", 2000)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 1600, i, true, PURPLE), mkC(r[1], 2600, i), mkC(r[2], 2800, i), mkC(r[3], 2000, i)] }))
  ]
});

const shiftTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [4500, 4500],
  rows: [
    new TableRow({ children: [mkH("Stop Running This", 4500), mkH("Start Running This Instead", 4500)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 4500, i), mkC(r[1], 4500, i)] }))
  ]
});

const metricsTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [2500, 2000, 2000, 2500],
  rows: [
    new TableRow({ children: [mkH("Metric", 2500), mkH("What It Tells You", 2000), mkH("Target", 2000), mkH("If It Misses, Do This", 2500)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 2500, i, true), mkC(r[1], 2000, i), mkC(r[2], 2000, i), mkC(r[3], 2500, i)] }))
  ]
});

// ════════════════════════════════════════════════════════════
// DOCUMENT
// ════════════════════════════════════════════════════════════
const doc = new Document({
  numbering: { config: [
    { reference: "bul", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    { reference: "num", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] }
  ]},
  styles: {
    default: { document: { run: { font: "Arial", size: 20 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 36, bold: true, font: "Arial", color: PURPLE }, paragraph: { spacing: { before: 300, after: 120 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 26, bold: true, font: "Arial", color: PURPLE }, paragraph: { spacing: { before: 220, after: 100 }, outlineLevel: 1 } }
    ]
  },
  sections: [{ properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1260, bottom: 1260, left: 1260 } } },
  children: [

    // ══════════════════════════ COVER ══════════════════════════
    sp(300),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 28, bold: true, color: PURPLE_SOFT })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 120 }, children: [new TextRun({ text: "The Feminine Funnel Ad Playbook", font: "Arial", size: 48, bold: true, color: PURPLE })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: "For Jacques | Media, Tech, and Meta Ads", font: "Arial", size: 24, bold: true, color: GOLD })] }),
    div(GOLD),
    sp(40),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "How to stop running ads that describe Luxora", font: "Arial", size: 20, italic: true, color: MID })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "and start running ads that make her feel completely understood.", font: "Arial", size: 20, italic: true, color: MID })] }),
    sp(60),
    box([
      "A NOTE BEFORE YOU READ THIS",
      " ",
      "This is not a technical ad manual. You already know how to build ads.",
      " ",
      "This is a mindset document. It exists because the most technically perfect ad",
      "in the world will not convert if the first line makes a med spa owner feel",
      "like she is being sold to instead of understood.",
      " ",
      "Read this once all the way through. Then go back to your active ads",
      "and ask yourself: does this hook describe Luxora, or does it describe her?",
      " ",
      "That question is the whole shift."
    ], LIGHT_PUR),
    sp(80),

    // ══════════════════════════ SECTION 1 ══════════════════════════
    pb(),
    ...sectionLabel("SECTION 1", "The Mindset Shift That Changes Everything"),

    body("Right now, most ads in the med spa space open with one of these:"),
    sp(30),
    box([
      "\"We help med spas grow revenue...\"",
      "\"Book a free strategy call with our team...\"",
      "\"Our 90-Day Growth Engine is designed to...\"",
    ], GRAY, MID),
    sp(40),
    body("Those lines speak to the brain. They describe a service. They ask the owner to evaluate an offer."),
    sp(20),
    body("But the owner scrolling Instagram at 10pm after a 12-hour day is not in evaluation mode."),
    sp(20),
    body("She is in feeling mode. And what she is feeling is this:"),
    sp(40),
    box([
      "\"I am exhausted from carrying this business alone.\"",
      "\"I know I am capable of more but something is not clicking.\"",
      "\"I did not start this to feel stuck, overwhelmed, and guessing.\"",
    ], LIGHT_PUR, DARK),
    sp(40),
    body("That is where Luxora's ads need to meet her. Not at the offer. At the feeling."),
    sp(40),
    body("When an ad opens with a line that makes her think 'how did they know that about me,' she stops scrolling. She watches. She clicks. She applies."),
    sp(40),
    body("That is the only shift this document is asking you to make.", true),
    sp(60),
    div(),

    h2("The Two Types of Ads: Brain Ads vs. Body Ads"),
    body("Every ad you run falls into one of these two categories. The goal is to move Luxora's ad library toward the right column."),
    sp(40),
    shiftTable([
      ["Brain Ad: opens with what Luxora does", "Body Ad: opens with what she feels"],
      ["'We help med spas grow revenue'", "'You didn't start this business to feel stuck at the same number for three years'"],
      ["'Book a free strategy call'", "'If this is landing for you, here is the next step. No pitch. Just clarity.'"],
      ["'Our Growth Engine installs systems across five areas'", "'There is a version of your clinic that runs without you holding everything together. You have seen it. You just have not been shown how to build it yet.'"],
      ["'Limited spots available this month'", "'We have three spots open. If you are in that season, you already know.'"],
      ["Proof: what Luxora has done", "Proof: what she will no longer feel once it is fixed"]
    ]),
    sp(40),
    italic("The right column does not replace the left. It comes first. Emotion opens the door. Logic walks through it."),
    sp(80),

    // ══════════════════════════ SECTION 2 ══════════════════════════
    pb(),
    ...sectionLabel("SECTION 2", "The Emotional Psychology Stack"),

    body("Leanne Lopez Mosley (RichQueen) and Shoshanna Raven both use the same five emotional layers in their content and ads. Every piece they produce hits at least one. Below is how each layer translates into Luxora ad copy Jacques can write and test."),
    sp(60),

    h3("Layer 1: Validation"),
    body("The owner's first fear is that she is the problem. She has tried things that did not work. She wonders if she is not smart enough or disciplined enough. Your ad needs to remove that fear in the first sentence."),
    sp(30),
    box([
      "The principle: \"You are not the problem.\"",
      " ",
      "Luxora ad version:",
      "  \"You're not bad at business. You've just never been given a system that actually works.\"",
      "  \"It's not that your team can't sell. It's that they've never been taught how.\"",
      "  \"Most med spa owners we talk to aren't failing. They're just exhausted.\""
    ], LIGHT_PUR),
    sp(60),

    h3("Layer 2: Articulation of Hidden Pain"),
    body("Say the thing she has not been able to say out loud. When your ad names a feeling she has been carrying alone, she feels immediately understood. That feeling of being understood is what earns the click."),
    sp(30),
    box([
      "The principle: Say what they feel but have not said.",
      " ",
      "Luxora ad version:",
      "  \"You're bringing in leads. But deep down you know your business isn't stable.\"",
      "  \"You're busy all day and still anxious about revenue at night.\"",
      "  \"You can have leads coming in and still feel completely unstable.\""
    ], LIGHT_GOLD),
    sp(60),

    h3("Layer 3: Future Identity"),
    body("Do not tell her what she will get. Tell her who she will become. The version of herself she is trying to reach is the real purchase. The Growth Engine is just the vehicle."),
    sp(30),
    box([
      "The principle: Sell the future self, not the deliverable.",
      " ",
      "Luxora ad version:",
      "  \"The version of you that runs a $2M clinic doesn't chase leads.\"",
      "  \"She knows her numbers. Her team performs. Her systems work.\"",
      "  \"There is a version of your business that runs smoothly, books consistently, and doesn't rely on you for everything. You've seen it. You've felt it. You just haven't been shown how to build it yet.\""
    ], LIGHT_PUR),
    sp(60),

    h3("Layer 4: Safety"),
    body("She has been burned before. She has spent money on agencies and seen nothing. The ad has to remove the fear of making another bad decision before it ever mentions an offer."),
    sp(30),
    box([
      "The principle: Remove the fear of the wrong decision.",
      " ",
      "Luxora ad version:",
      "  \"We don't run ads until your backend is ready.\"",
      "  \"If we can't find real opportunity in your numbers, you don't move forward.\"",
      "  \"We built this for the owner who is done gambling on marketing.\""
    ], LIGHT_GOLD),
    sp(60),

    h3("Layer 5: Authority Without Ego"),
    body("Luxora has something most marketing agencies do not: real inside-the-industry experience. Bethany has lived it. That is the authority proof. The ad should reference it without bragging."),
    sp(30),
    box([
      "The principle: Show you know, without telling them you're the best.",
      " ",
      "Luxora ad version:",
      "  \"We've seen this exact pattern across hundreds of clinics. There's a reason you're stuck here.\"",
      "  \"Most med spas leave $40K/year on the table in their front desk follow-up alone. We know because we've been inside enough of them to map it.\"",
      "  \"Bethany ran a med spa. She knows what it feels like from the inside. That's why Luxora is built differently.\""
    ], LIGHT_PUR),
    sp(80),

    // ══════════════════════════ SECTION 3 ══════════════════════════
    pb(),
    ...sectionLabel("SECTION 3", "The Luxora Ad Library: Build These First"),

    body("Below are the six ad types Luxora needs running simultaneously. Three cold, three warm. Each is built on a different emotional layer so the prospect feels understood from multiple angles across multiple touchpoints."),
    sp(40),

    h2("Cold Traffic Ads (She Has Never Heard of Luxora)"),
    sp(30),
    adTable([
      [
        "The Exhaustion Ad",
        "\"Most med spa owners we talk to aren't failing. They're just exhausted.\"",
        "Deepens the feeling: busy all day, still anxious at night, inconsistent months, carrying everything alone. Validates. Then: 'This isn't a discipline problem. It's a systems problem.' No offer until the last line.",
        "\"If this is landing, we can map out where your revenue is actually leaking. No pitch. Link in bio.\""
      ],
      [
        "The Identity Gap Ad",
        "\"You didn't start your med spa to feel stuck at the same number for three years.\"",
        "Paint the gap between who she is and who she knows she can be. Speak to freedom, income, impact. Then: 'Somewhere along the way it started to feel heavier than it should. That's not a you problem.' Bethany talking head, 25 seconds.",
        "\"Apply for a Market Blueprint. We'll show you exactly what's in the way.\""
      ],
      [
        "The Survival vs. Scale Ad",
        "\"If you're constantly chasing new leads, your business isn't scaling. It's surviving.\"",
        "One line. Let it land. Then: 'And deep down you already know that.' Short pause. 'The clinics that scale past this point don't operate like this. They have structure behind everything.' Authority without ego.",
        "\"See what that structure looks like for your clinic.\""
      ]
    ]),
    sp(60),

    h2("Warm Retargeting Ads (She Has Seen Luxora Before)"),
    sp(30),
    adTable([
      [
        "The 'You've Seen Us' Ad",
        "\"You've been watching us for a while. Here's what we actually do in 90 days.\"",
        "Direct, warm, earned. Walk through the five pillars of the Growth Engine but frame each one as a problem she no longer has. Not 'we install a follow-up system.' Instead: 'You stop losing 30% of your booked appointments to no-shows.' Outcome language only.",
        "\"If you're ready, here's how to apply.\""
      ],
      [
        "The Client Result Ad",
        "\"She came to us doing $74K/month. Busy, exhausted, inconsistent. 11 weeks later: $108K.\"",
        "One client. One specific number. One human detail about how she felt before. Then: what we changed first (show rate and front desk protocol, not a new ad campaign). Keep the proof specific and emotional, not clinical.",
        "\"Your Market Blueprint is free. See what's possible for your clinic.\""
      ],
      [
        "The Safety Ad",
        "\"You've probably spent money on marketing that didn't move the needle. We built Luxora for exactly that reason.\"",
        "Address the objection she already has before she can voice it. Bethany: 'We don't run ads until the backend is ready. Because putting more leads into a broken system just means more leads you can't close.' Then: what we fix first.",
        "\"We have three spots open this month. Apply if you're ready.\""
      ]
    ]),
    sp(60),
    div(),

    h2("The Luxora Emotional Post Framework (For Ad Copy Structure)"),
    body("Use this sequence for any ad that is longer than a single statement. It works for video scripts, carousel copy, and static ad body text."),
    sp(40),
    box([
      "STEP 1: Call out the identity or the pain",
      "  'You didn't start your med spa to feel like this...'",
      " ",
      "STEP 2: Deepen the emotion without explaining it away",
      "  'Constantly busy. Still unsure if next month will be okay.'",
      " ",
      "STEP 3: Validate (remove the self-blame)",
      "  'And no one talks about this part.'",
      " ",
      "STEP 4: Reframe the problem",
      "  'This isn't a lead problem.'",
      " ",
      "STEP 5: Introduce the real belief",
      "  'It's a system problem.'",
      " ",
      "STEP 6: Paint the future identity",
      "  'The clinics that scale don't operate like this. They have structure behind everything.'",
      " ",
      "STEP 7: Soft CTA only",
      "  'If you want to see what's actually holding you back, we can map it out.'"
    ], LIGHT_PUR),
    sp(80),

    // ══════════════════════════ SECTION 4 ══════════════════════════
    pb(),
    ...sectionLabel("SECTION 4", "Audience and Technical Setup"),

    body("The emotional copy is only half the equation. The right message still fails if it is reaching the wrong person. These are the audience parameters that match Luxora's ideal client."),
    sp(60),

    h2("Cold Audiences"),
    bul("Job title targeting: medical spa owner, aesthetic clinic owner, practice manager, medical director, cosmetic nurse, aesthetician (business owner variant)"),
    bul("Interests: aesthetic medicine, practice management, cosmetic dermatology, small business ownership, entrepreneurship, GoHighLevel, MedSpa Mentor"),
    bul("Household income: top 25% or higher"),
    bul("Age: 28 to 55"),
    bul("Geography: United States, exclude major metro areas if CPL is high (test with and without)"),
    bul("Lookalike: build a 1% lookalike from the current client email list and existing Blueprint applicants"),
    sp(40),

    h2("Warm Retargeting Audiences (Always Running)"),
    bul("Instagram profile visitors: 90 days"),
    bul("Website visitors: 60 days (all pages)"),
    bul("Video viewers: 50% watch time, 30 days"),
    bul("Email list upload: current and past clients, Blueprint applicants"),
    bul("Engagement audience: anyone who saved, commented on, or shared a Luxora post in the last 90 days"),
    sp(40),

    h2("Budget Split"),
    box([
      "Cold traffic (awareness and prospecting): 65% of total budget",
      "Warm retargeting (conversion): 35% of total budget",
      " ",
      "Starting monthly ad budget recommendation: $1,500 to $2,500",
      "Once CPL is consistently under $40: scale cold budget by 20% per week until it breaks, then pull back 10% and hold."
    ], LIGHT_GOLD),
    sp(60),
    div(),

    h2("What to Test First (Week 1 to Week 4)"),
    bul("Week 1 to 2: Run the Exhaustion Ad and the Identity Gap Ad against each other. Same audience. Same budget. Different hooks. Keep the winner."),
    bul("Week 2 to 3: Add the Survival vs. Scale Ad as a third cold variant. Let it run alongside the cold winner."),
    bul("Week 3 to 4: Launch all three warm retargeting ads. Warm audiences should see one ad per week in rotation. Do not repeat the same ad to the same warm audience more than twice."),
    bul("Week 4: Report CTR, CPL, and conversion to Blueprint application to Eric. Kill the lowest performer. Double the budget on the winner. Introduce one new hook variant using a different emotional layer."),
    sp(80),

    // ══════════════════════════ SECTION 5 ══════════════════════════
    pb(),
    ...sectionLabel("SECTION 5", "Metrics: What to Track and What to Do When It Misses"),

    metricsTable([
      ["Hook rate (ThruPlays / Impressions)", "Is the opening line stopping the scroll?", "Over 20% for video", "Rewrite the first sentence. The emotion is not specific enough yet."],
      ["CTR (link click-through rate)", "Does the body copy earn the click?", "Over 1.5% for cold / Over 3% for warm", "Test a shorter body. Remove any line that sounds like a pitch."],
      ["Cost per lead (Blueprint application)", "Is the whole ad earning the action?", "Under $40 cold / Under $20 warm", "Check landing page next. The ad may be working but the page may be losing her."],
      ["Cost per click", "Is the audience right?", "Under $2.50", "Narrow the audience or shift to a more specific job title variant."],
      ["Conversion rate: click to Blueprint apply", "Is the landing page matching the ad's emotional promise?", "Over 15%", "The page opener must match the ad hook exactly. If the ad is about exhaustion, the page opens with exhaustion."]
    ]),
    sp(60),
    div(),

    h2("The Landing Page Rule"),
    body("This is the single most common reason a well-performing ad does not convert: the landing page breaks the emotional contract."),
    sp(40),
    box([
      "The rule: The first line of the landing page must emotionally mirror the hook of the ad that sent her there.",
      " ",
      "If the ad hook is: 'You didn't start your med spa to feel stuck at the same number for three years.'",
      "The landing page opens with: 'You already know something has to change.'",
      " ",
      "If the ad hook is: 'Most med spa owners aren't failing. They're just exhausted.'",
      "The landing page opens with: 'You've been carrying this longer than you should have to.'",
      " ",
      "She should land on the page and feel: yes. Exactly. Keep reading.",
      "If she lands and sees a logo and a list of program features, she is already gone."
    ], LIGHT_PUR),
    sp(80),

    // ══════════════════════════ SECTION 6 ══════════════════════════
    pb(),
    ...sectionLabel("SECTION 6", "Quick Reference: The Language That Works"),

    body("Keep this page bookmarked. When you are writing a hook and it sounds like a service description, replace it with one of these or use the structure to write your own."),
    sp(40),

    h3("Hooks That Work (Emotional Precision)"),
    box([
      "\"You didn't start your med spa to feel stuck at the same number for three years.\"",
      "\"Most med spa owners we talk to aren't failing. They're just exhausted.\"",
      "\"You can have leads coming in and still feel completely unstable.\"",
      "\"If you're constantly chasing new leads, your business isn't scaling. It's surviving.\"",
      "\"You're not bad at business. You've just never been given a system that actually works.\"",
      "\"You're busy all day and still anxious about revenue at night.\"",
      "\"The hardest part about owning a med spa that no one talks about is...\"",
      "\"The difference between a $500K clinic and a $2M clinic is not the number of leads.\""
    ], LIGHT_GOLD, DARK),
    sp(40),

    h3("CTAs That Work (Soft Conversion)"),
    box([
      "\"If this is landing for you, here is the next step. No pitch. Just clarity.\"",
      "\"Apply for a Market Blueprint. We will map your revenue gaps. If we can't find real growth, you keep the insight.\"",
      "\"We have three spots open this month. If you're in that season, you already know.\"",
      "\"If you want to see what's actually holding you back, we can map it out.\"",
      "\"Link in bio. No pressure. Just see if it's the right fit.\""
    ], LIGHT_PUR, DARK),
    sp(40),

    h3("Language to Remove From All Ad Copy"),
    box([
      "Remove: 'Book a free strategy call' (sounds like every other agency)",
      "Remove: 'Limited time offer' (pressure, not safety)",
      "Remove: 'We help med spas grow' (describes Luxora, not her)",
      "Remove: 'Our program includes...' (deliverable-first, not outcome-first)",
      "Remove: 'Don't miss out' (urgency without trust is noise)"
    ], GRAY, MID),
    sp(80),

    // ══════════════════════════ CLOSING ══════════════════════════
    pb(),
    sp(100),
    div(GOLD),
    sp(60),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Jacques, Here Is the One Thing to Remember", font: "Arial", size: 28, bold: true, color: PURPLE })] }),
    sp(40),
    body("The ad does not close the client. Bethany closes the client.", false, MID),
    body("The ad has one job: make her feel understood enough to take one more step.", false, MID),
    sp(40),
    body("If the hook makes a med spa owner stop and think 'how did they know that about me'... the ad is working.", true, PURPLE),
    sp(40),
    body("If the hook makes her think 'oh, this is an agency ad'... rewrite the first line.", false, MID),
    sp(60),
    div(GOLD),
    sp(40),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 20, after: 20 }, children: [new TextRun({ text: "The Luxora Collective | theluxoracollective.co", font: "Arial", size: 18, italic: true, color: PURPLE_SOFT })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 20 }, children: [new TextRun({ text: "Bethany | Co-Founder and CEO", font: "Arial", size: 17, color: MID })] }),

  ]}]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("/mnt/user-data/outputs/Jacques_Feminine_Funnel_Ad_Playbook.docx", buf);
  console.log("Jacques doc done.");
});

