const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

// ─── COLORS ─────────────────────────────────────────────────────────────────
const PURPLE      = "3D1F6E";
const PURPLE_MID  = "6B4DAA";
const PURPLE_SOFT = "9B7FCC";
const GOLD        = "B8922A";
const ROSE        = "9E4F6A";
const ROSE_LIGHT  = "F9EDF3";
const LIGHT_PUR   = "EDE5F7";
const LIGHT_GOLD  = "FDF6E3";
const GRAY        = "F4F4F4";
const WHITE       = "FFFFFF";
const DARK        = "1A1A1A";
const MID         = "555555";

// ─── BORDERS ────────────────────────────────────────────────────────────────
const nb = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: nb, bottom: nb, left: nb, right: nb };
const tb = (c = "CCCCCC") => ({ style: BorderStyle.SINGLE, size: 1, color: c });
const borders = { top: tb(), bottom: tb(), left: tb(), right: tb() };
const purpB = { top: tb(PURPLE), bottom: tb(PURPLE), left: tb(PURPLE), right: tb(PURPLE) };
const roseB = { top: tb(ROSE), bottom: tb(ROSE), left: tb(ROSE), right: tb(ROSE) };

// ─── PRIMITIVES ──────────────────────────────────────────────────────────────
const sp = (n = 60) => new Paragraph({ spacing: { before: n, after: n }, children: [new TextRun("")] });
const pb = () => new Paragraph({ children: [new PageBreak()] });

const div = (c = PURPLE) => new Paragraph({
  spacing: { before: 100, after: 100 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: c, space: 1 } },
  children: [new TextRun("")]
});

const h1 = (t) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 300, after: 120 },
  children: [new TextRun({ text: t, font: "Arial", size: 36, bold: true, color: PURPLE })]
});

const h2 = (t, c = PURPLE) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 220, after: 100 },
  children: [new TextRun({ text: t, font: "Arial", size: 26, bold: true, color: c })]
});

const h3 = (t, c = GOLD) => new Paragraph({
  spacing: { before: 160, after: 70 },
  children: [new TextRun({ text: t, font: "Arial", size: 22, bold: true, color: c })]
});

const body = (t, bold = false, c = DARK) => new Paragraph({
  spacing: { before: 55, after: 55 },
  children: [new TextRun({ text: t, font: "Arial", size: 20, bold, color: c })]
});

const italic = (t, c = MID) => new Paragraph({
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text: t, font: "Arial", size: 18, italic: true, color: c })]
});

const bul = (t, bold = false) => new Paragraph({
  numbering: { reference: "bul", level: 0 },
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text: t, font: "Arial", size: 20, bold, color: DARK })]
});

const tagged = (label, t, lc = PURPLE) => new Paragraph({
  spacing: { before: 60, after: 60 },
  children: [
    new TextRun({ text: label + ": ", font: "Arial", size: 20, bold: true, color: lc }),
    new TextRun({ text: t, font: "Arial", size: 20, color: DARK })
  ]
});

const box = (lines, fill = LIGHT_PUR, tc = DARK) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [9000],
  rows: lines.map(l => new TableRow({ children: [new TableCell({
    borders: noBorders, width: { size: 9000, type: WidthType.DXA },
    shading: { fill, type: ShadingType.CLEAR },
    margins: { top: 65, bottom: 65, left: 220, right: 220 },
    children: [new Paragraph({ spacing: { before: l.trim() === "" ? 20 : 40, after: l.trim() === "" ? 20 : 40 }, children: [new TextRun({ text: l, font: "Arial", size: l.trim() === "" ? 8 : 19, color: tc })] })]
  })]})
)});

const sectionLabel = (n, t, c = PURPLE) => [
  sp(20),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: n, font: "Arial", size: 20, bold: true, color: GOLD })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: t, font: "Arial", size: 32, bold: true, color: c })] }),
  div(),
  sp(20)
];

function mkH(t, w, fill = PURPLE) {
  return new TableCell({ borders: purpB, width: { size: w, type: WidthType.DXA }, shading: { fill, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 130, right: 130 }, children: [new Paragraph({ children: [new TextRun({ text: t, font: "Arial", size: 19, bold: true, color: WHITE })] })] });
}
function mkC(t, w, i, bold = false, c = DARK) {
  return new TableCell({ borders, width: { size: w, type: WidthType.DXA }, shading: { fill: i % 2 === 0 ? GRAY : WHITE, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 130, right: 130 }, children: [new Paragraph({ children: [new TextRun({ text: t, font: "Arial", size: 18, bold, color: c })] })] });
}

const shiftTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [4500, 4500],
  rows: [
    new TableRow({ children: [mkH("Stop Writing This", 4500), mkH("Start Writing This Instead", 4500)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 4500, i, false, MID), mkC(r[1], 4500, i, false, DARK)] }))
  ]
});

const weekTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [900, 1600, 3500, 1600, 1400],
  rows: [
    new TableRow({ children: [mkH("Day", 900), mkH("Type", 1600), mkH("Hook / Example Content", 3500), mkH("Format", 1600), mkH("Deliver By", 1400)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 900, i, true, PURPLE), mkC(r[1], 1600, i, true), mkC(r[2], 3500, i), mkC(r[3], 1600, i), mkC(r[4], 1400, i)] }))
  ]
});

const captionTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [2000, 7000],
  rows: [
    new TableRow({ children: [mkH("Post Type", 2000), mkH("Full Caption Framework", 7000)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 2000, i, true, PURPLE), mkC(r[1], 7000, i)] }))
  ]
});

const trustTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [1600, 2200, 2600, 2600],
  rows: [
    new TableRow({ children: [mkH("Trust Layer", 1600), mkH("What It Does", 2200), mkH("Luxora Example", 2600), mkH("Who Provides the Asset", 2600)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 1600, i, true, PURPLE), mkC(r[1], 2200, i), mkC(r[2], 2600, i), mkC(r[3], 2600, i)] }))
  ]
});

// ════════════════════════════════════════════════════════════
// DOCUMENT
// ════════════════════════════════════════════════════════════
const doc = new Document({
  numbering: { config: [
    { reference: "bul", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    { reference: "num", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] }
  ]},
  styles: {
    default: { document: { run: { font: "Arial", size: 20 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 36, bold: true, font: "Arial", color: PURPLE }, paragraph: { spacing: { before: 300, after: 120 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 26, bold: true, font: "Arial", color: PURPLE }, paragraph: { spacing: { before: 220, after: 100 }, outlineLevel: 1 } }
    ]
  },
  sections: [{ properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1260, bottom: 1260, left: 1260 } } },
  children: [

    // ══════════════════════════ COVER ══════════════════════════
    sp(300),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 28, bold: true, color: PURPLE_SOFT })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 120 }, children: [new TextRun({ text: "The Feminine Content Playbook", font: "Arial", size: 48, bold: true, color: PURPLE })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: "For Keisha | Southern Social | Organic Content and Social Media", font: "Arial", size: 22, bold: true, color: GOLD })] }),
    div(GOLD),
    sp(40),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "How to stop creating content that describes what Luxora does", font: "Arial", size: 20, italic: true, color: MID })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "and start creating content that makes her feel completely seen.", font: "Arial", size: 20, italic: true, color: MID })] }),
    sp(60),
    box([
      "A NOTE BEFORE YOU READ THIS",
      " ",
      "This is not a posting schedule. You already know how to schedule content.",
      " ",
      "This is a writing and strategy document. It exists because content that describes",
      "Luxora gets ignored. Content that describes how a med spa owner feels at 10pm",
      "on a Tuesday night gets saved, shared, and turned into a DM.",
      " ",
      "Read this once through. Then go back to the last five posts you scheduled",
      "and ask: does this sound like it is about Luxora, or does it sound like it is about her?",
      " ",
      "That one question changes everything."
    ], LIGHT_PUR),
    sp(80),

    // ══════════════════════════ SECTION 1 ══════════════════════════
    pb(),
    ...sectionLabel("SECTION 1", "The Mindset Shift: From Marketing to Mirror"),

    body("The most powerful thing content can do is make someone feel seen."),
    sp(20),
    body("Not impressed. Not educated. Seen."),
    sp(40),
    body("When a med spa owner reads a Luxora post and thinks 'this is exactly what I have been feeling and I have never heard anyone say it out loud before,' something shifts. She does not just follow the account. She trusts the account. And trust is what sells."),
    sp(40),
    body("Right now the content likely does one of three things:"),
    bul("Describes Luxora and what Luxora offers"),
    bul("Shares tactical advice about med spa marketing"),
    bul("Posts proof of results without emotional context"),
    sp(40),
    body("None of those are wrong. But none of them, on their own, build the kind of trust that makes a prospect feel safe enough to apply for a call with Bethany."),
    sp(40),
    body("The shift is this:", true),
    sp(20),
    box([
      "Stop: writing about Luxora",
      "Start: writing about her",
      " ",
      "Stop: explaining what the problem is",
      "Start: naming how the problem feels",
      " ",
      "Stop: telling her what she gets",
      "Start: showing her who she becomes"
    ], LIGHT_PUR),
    sp(60),
    div(),

    h2("The Two Content Types: Information vs. Emotion"),
    body("Both types have a role. But the ratio in most B2B content is wrong. Most accounts post 80% information and 20% emotion. The accounts that build trust fast flip it."),
    sp(40),
    shiftTable([
      ["'Here are 5 ways to improve your show rate'", "'You're losing 30% of your booked appointments and it has nothing to do with the patients. Here's what's actually happening.'"],
      ["'Luxora helps med spas increase revenue'", "'You didn't start this business to feel stuck at the same number for three years.'"],
      ["'Book a Market Blueprint call today'", "'If this is landing for you, here is the next step. No pitch. Just clarity.'"],
      ["'Client result: revenue up 47% in 90 days'", "'She came to us exhausted, inconsistent, and doing $74K/month. 11 weeks later she crossed $108K. Here is the one thing we changed first.'"],
      ["'We fix your front desk follow-up system'", "'Your front desk isn't the problem. Nobody trained them to sell. Here's the difference.'"]
    ]),
    sp(40),
    italic("The right column is not softer. It is more precise. Emotional precision is not fluff. It is the difference between content that gets scrolled past and content that gets screenshotted."),
    sp(80),

    // ══════════════════════════ SECTION 2 ══════════════════════════
    pb(),
    ...sectionLabel("SECTION 2", "The Five Emotional Layers: What Every Post Should Do"),

    body("RichQueen (Leanne Lopez Mosley) and Shoshanna Raven both use these five layers in their content. When a post hits even one of these, it performs. When it hits two or three, it builds real trust. Use these as a checklist when writing captions."),
    sp(60),

    h3("Layer 1: Validation"),
    body("The med spa owner you are writing for has tried things that did not work. She has spent money on agencies, hired staff that turned over, run ads that did not convert. She quietly wonders if she is the problem."),
    sp(20),
    body("Your content needs to remove that fear. Not by telling her she is great. By naming the real cause."),
    sp(30),
    box([
      "Principle: 'You are not the problem.'",
      " ",
      "Luxora version examples:",
      "  'You're not bad at business. You've just never been given a system that actually works.'",
      "  'It's not that your team can't sell. It's that they've never been taught how.'",
      "  'You're not overwhelmed because you're weak. You're overwhelmed because you're carrying a system that was never built to scale.'"
    ], LIGHT_PUR),
    sp(60),

    h3("Layer 2: Articulation of Hidden Pain"),
    body("This is the one that makes people stop scrolling. When you name a feeling they have been carrying but have never heard anyone describe out loud, they feel immediately understood. That feeling is the fastest trust builder that exists."),
    sp(30),
    box([
      "Principle: Say what they feel but haven't said.",
      " ",
      "Luxora version examples:",
      "  'You can have leads coming in and still feel completely unstable.'",
      "  'You're busy all day and still anxious about next month's revenue at night.'",
      "  'You're doing all the things. The ads, the posts, the team meetings. And it still feels heavier than it should.'",
      "  'The hardest part about owning a med spa that no one talks about is...'"
    ], LIGHT_GOLD),
    sp(60),

    h3("Layer 3: Future Identity"),
    body("Do not tell her what she will get. Tell her who she will become. The outcome she actually wants is not more revenue. It is the feeling of running a business that works without her having to hold everything together. Sell that."),
    sp(30),
    box([
      "Principle: Sell the future self, not the deliverable.",
      " ",
      "Luxora version examples:",
      "  'The version of you that runs a $2M clinic doesn't chase leads. She knows her numbers. Her team performs. Her systems work.'",
      "  'There is a version of your business that books consistently and doesn't rely on you for everything. You've seen it. You've felt it. You just haven't been shown how to build it yet.'",
      "  'She still does the medicine she loves. The business just finally works underneath her.'"
    ], LIGHT_PUR),
    sp(60),

    h3("Layer 4: Safety"),
    body("She has been burned. A piece of content that removes the fear of making another bad decision will earn more trust than any case study. Luxora's 'no pitch, just clarity' framing is already a safety message. Use it everywhere."),
    sp(30),
    box([
      "Principle: Remove the fear of the wrong decision.",
      " ",
      "Luxora version examples:",
      "  'We don't run ads until the backend is ready. Because more leads in a broken system is just more chaos.'",
      "  'If we can't find real opportunity in your numbers, you don't move forward. That's the promise.'",
      "  'We built this for the owner who is done gambling on marketing.'"
    ], LIGHT_GOLD),
    sp(60),

    h3("Layer 5: Authority Without Ego"),
    body("Bethany's edge is that she has been inside a med spa. She is not a marketer who learned about med spas. She is an operator who built a methodology. That is the authority. Reference it without bragging."),
    sp(30),
    box([
