const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

// ─── COLORS ─────────────────────────────────────────────────────────────────
const PURPLE      = "3D1F6E";
const PURPLE_MID  = "6B4DAA";
const PURPLE_SOFT = "9B7FCC";
const GOLD        = "B8922A";
const ROSE        = "7A3050";
const LIGHT_PUR   = "EDE5F7";
const LIGHT_GOLD  = "FDF6E3";
const LIGHT_ROSE  = "F9EDF3";
const GRAY        = "F4F4F4";
const GRAY_MID    = "E0E0E0";
const WHITE       = "FFFFFF";
const DARK        = "1A1A1A";
const MID         = "555555";
const SOFT        = "888888";

// ─── BORDERS ────────────────────────────────────────────────────────────────
const nb  = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: nb, bottom: nb, left: nb, right: nb };
const tb  = (c = "CCCCCC") => ({ style: BorderStyle.SINGLE, size: 1, color: c });
const borders    = { top: tb(), bottom: tb(), left: tb(), right: tb() };
const purpBorder = { top: tb(PURPLE), bottom: tb(PURPLE), left: tb(PURPLE), right: tb(PURPLE) };
const goldBorder = { top: tb(GOLD),   bottom: tb(GOLD),   left: tb(GOLD),   right: tb(GOLD) };

// ─── PRIMITIVES ──────────────────────────────────────────────────────────────
const sp  = (n = 60) => new Paragraph({ spacing: { before: n, after: n }, children: [new TextRun("")] });
const pb  = ()       => new Paragraph({ children: [new PageBreak()] });

const div = (c = PURPLE, thickness = 6) => new Paragraph({
  spacing: { before: 100, after: 100 },
  border: { bottom: { style: BorderStyle.SINGLE, size: thickness, color: c, space: 1 } },
  children: [new TextRun("")]
});

const thin = () => new Paragraph({
  spacing: { before: 40, after: 40 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD", space: 1 } },
  children: [new TextRun("")]
});

// Headings
const h1 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 320, after: 120 }, children: [new TextRun({ text: t, font: "Arial", size: 36, bold: true, color: PURPLE })] });
const h2 = (t, c = PURPLE) => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 100 }, children: [new TextRun({ text: t, font: "Arial", size: 26, bold: true, color: c })] });
const h3 = (t, c = GOLD)   => new Paragraph({ spacing: { before: 180, after: 70  }, children: [new TextRun({ text: t, font: "Arial", size: 22, bold: true, color: c })] });

// Body text
const body   = (t, bold = false, c = DARK) => new Paragraph({ spacing: { before: 55, after: 55 }, children: [new TextRun({ text: t, font: "Arial", size: 20, bold, color: c })] });
const italic = (t, c = MID)               => new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: t, font: "Arial", size: 18, italic: true, color: c })] });
const small  = (t, c = SOFT)              => new Paragraph({ spacing: { before: 30, after: 30 }, children: [new TextRun({ text: t, font: "Arial", size: 17, color: c })] });

// Lists
const bul = (t, bold = false) => new Paragraph({ numbering: { reference: "bul", level: 0 }, spacing: { before: 40, after: 40 }, children: [new TextRun({ text: t, font: "Arial", size: 20, bold, color: DARK })] });

// Tag/label
const tag = (label, t, lc = PURPLE) => new Paragraph({ spacing: { before: 60, after: 60 }, children: [new TextRun({ text: label + ": ", font: "Arial", size: 20, bold: true, color: lc }), new TextRun({ text: t, font: "Arial", size: 20, color: DARK })] });

// Section banner
const sectionBanner = (num, title, subtitle = "") => [
  pb(),
  sp(20),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 40 }, children: [new TextRun({ text: num, font: "Arial", size: 22, bold: true, color: GOLD })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: subtitle ? 60 : 100 }, children: [new TextRun({ text: title, font: "Arial", size: 38, bold: true, color: PURPLE })] }),
  ...(subtitle ? [new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: subtitle, font: "Arial", size: 20, italic: true, color: MID })] })] : []),
  div(),
  sp(20)
];

// Callout box
const box = (lines, fill = LIGHT_PUR, tc = DARK, headerBold = false) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [9000],
  rows: lines.map((l, idx) => new TableRow({ children: [new TableCell({
    borders: noBorders,
    width: { size: 9000, type: WidthType.DXA },
    shading: { fill, type: ShadingType.CLEAR },
    margins: { top: 60, bottom: 60, left: 230, right: 230 },
    children: [new Paragraph({
      spacing: { before: l.trim() === "" ? 18 : 40, after: l.trim() === "" ? 18 : 40 },
      children: [new TextRun({
        text: l,
        font: "Arial",
        size: l.trim() === "" ? 8 : 19,
        color: l.trim() === "" ? WHITE : tc,
        bold: headerBold && idx === 0
      })]
    })]
  })]})
)});

// Script box (for call scripts and Reel scripts)
const scriptBox = (lines, fill = LIGHT_ROSE) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [9000],
  rows: lines.map(l => new TableRow({ children: [new TableCell({
    borders: { top: tb(ROSE), bottom: tb(ROSE), left: tb(ROSE), right: tb(ROSE) },
    width: { size: 9000, type: WidthType.DXA },
    shading: { fill, type: ShadingType.CLEAR },
    margins: { top: 70, bottom: 70, left: 250, right: 250 },
    children: [new Paragraph({
      spacing: { before: l.trim() === "" ? 16 : 44, after: l.trim() === "" ? 16 : 44 },
      children: [new TextRun({
        text: l, font: "Arial",
        size: l.trim() === "" ? 8 : 20,
        color: l.trim() === "" ? WHITE : DARK,
        italic: l.startsWith("[") && l.endsWith("]"),
        bold: l.startsWith("BETHANY:") || l.startsWith("HOOK:") || l.startsWith("WEEK") || (l.toUpperCase() === l && l.trim().length > 0 && !l.startsWith("["))
      })]
    })]
  })]})
)});

// Post card
const postCard = (dayLabel, postType, caption, reelScript = null) => [
  sp(30),
  new Paragraph({
    spacing: { before: 60, after: 0 },
    children: [
      new TextRun({ text: dayLabel + "  ", font: "Arial", size: 22, bold: true, color: PURPLE }),
      new TextRun({ text: postType, font: "Arial", size: 19, bold: true, color: GOLD })
    ]
  }),
  thin(),
  sp(20),
  box(caption.split("\n"), LIGHT_PUR, DARK),
  ...(reelScript ? [sp(20), italic("REEL SCRIPT (word-for-word):"), scriptBox(reelScript.split("\n"), LIGHT_ROSE)] : []),
  sp(40)
];

// Call script segment
const callSegment = (heading, lines, fill = LIGHT_PUR) => [
  h3(heading, ROSE),
  box(lines, fill, DARK),
  sp(30)
];

// ─── TABLE HELPERS ────────────────────────────────────────────────────────────
function mkH(t, w, fill = PURPLE) {
  return new TableCell({ borders: purpBorder, width: { size: w, type: WidthType.DXA }, shading: { fill, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 130, right: 130 }, children: [new Paragraph({ children: [new TextRun({ text: t, font: "Arial", size: 19, bold: true, color: WHITE })] })] });
}
function mkC(t, w, i, bold = false, c = DARK) {
  return new TableCell({ borders, width: { size: w, type: WidthType.DXA }, shading: { fill: i % 2 === 0 ? GRAY : WHITE, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 130, right: 130 }, children: [new Paragraph({ children: [new TextRun({ text: t, font: "Arial", size: 18, bold, color: c })] })] });
}
function mkGH(t, w) { return mkH(t, w, GOLD); }

const funnelTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [1800, 2200, 2500, 2500],
  rows: [
    new TableRow({ children: [mkH("Stage", 1800), mkH("What Happens", 2200), mkH("Luxora Action", 2500), mkH("Owner", 2500)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 1800, i, true, PURPLE), mkC(r[1], 2200, i), mkC(r[2], 2500, i), mkC(r[3], 2500, i)] }))
  ]
});

const weekSummaryTable = (rows) => new Table({
  width: { size: 9000, type: WidthType.DXA },
  columnWidths: [700, 1600, 3800, 2900],
  rows: [
    new TableRow({ children: [mkH("Day", 700), mkH("Post Type", 1600), mkH("Hook", 3800), mkH("Assigned To", 2900)] }),
    ...rows.map((r, i) => new TableRow({ children: [mkC(r[0], 700, i, true, PURPLE), mkC(r[1], 1600, i, true), mkC(r[2], 3800, i), mkC(r[3], 2900, i, false, PURPLE_MID)] }))
  ]
});

// ════════════════════════════════════════════════════════════
// DOCUMENT
// ════════════════════════════════════════════════════════════
const doc = new Document({
  numbering: { config: [
    { reference: "bul", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] }
  ]},
  styles: {
    default: { document: { run: { font: "Arial", size: 20 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 36, bold: true, font: "Arial", color: PURPLE }, paragraph: { spacing: { before: 320, after: 120 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 26, bold: true, font: "Arial", color: PURPLE }, paragraph: { spacing: { before: 240, after: 100 }, outlineLevel: 1 } }
    ]
  },
  sections: [{ properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1260, bottom: 1260, left: 1260 } } },
  children: [

    // ══════════════════════════════════════════
    // COVER
    // ══════════════════════════════════════════
    sp(280),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 26, bold: true, color: PURPLE_SOFT })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 }, children: [new TextRun({ text: "The Complete Feminine Funnel", font: "Arial", size: 50, bold: true, color: PURPLE })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "Content  |  Scripts  |  Funnels  |  Discovery Call", font: "Arial", size: 24, bold: true, color: GOLD })] }),
    div(GOLD),
    sp(40),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 40 }, children: [new TextRun({ text: "30 days of word-for-word posts. Every Reel scripted. Full funnel mapped.", font: "Arial", size: 20, italic: true, color: MID })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "From first impression to booked call to closed client.", font: "Arial", size: 20, italic: true, color: MID })] }),
    sp(50),
    box([
      "HOW TO USE THIS DOCUMENT",
      " ",
      "Bethany: This is your full operating system for the next 30 days. The posts are written. The Reel scripts are word-for-word. The call script is ready.",
      " ",
      "Jacques: Your ad copy lives in the hooks of these posts. Pull any Day 1, 3, 4, 8, 15, or 22 caption as the body of a cold ad. The emotional language is already built.",
      " ",
      "Keisha (Southern Social): Post from Part 2 verbatim. Do not rewrite the substance. You can adjust formatting for the platform. The emotional arc of each post is intentional.",
      " ",
      "Bethany records the Reel scripts exactly as written. First take is usually the best take. Do not over-produce."
    ], LIGHT_PUR),
    sp(80),

    // ══════════════════════════════════════════
    // THE FULL FUNNEL MAP
    // ══════════════════════════════════════════
    ...sectionBanner("THE LUXORA SYSTEM", "Content to Closed Client", "How every piece of this document connects into one machine"),

    body("Every post, every Reel, every ad, and every DM in this document flows into the same destination: Bethany on a discovery call with a med spa owner who already feels understood before the call even starts."),
    sp(40),
    body("That is the only goal. Not followers. Not likes. Trust that converts."),
    sp(60),
    funnelTable([
      ["COLD CONTENT", "She sees a post or ad that describes exactly how she feels", "Day 1 to 7 posts run organically. Jacques boosts any post that hits 500+ views. Cold ad uses the same hook language.", "Southern Social posts / Jacques boosts and runs ads"],
      ["WARM ENGAGEMENT", "She follows, saves, or comments. She starts consuming more content.", "Week 2 and 3 content deepens trust. She sees proof, personal story, and authority content. Retargeting ads begin.", "Southern Social continues schedule / Jacques retargets engagers"],
      ["TRIGGERED ACTION", "She DMs, clicks a link, or downloads something. She has raised her hand.", "Aanchal responds to DMs using warm templates. Low-ticket Playbook or free Blueprint is offered based on where she is.", "Aanchal monitors DMs daily / Jacques retargeting ad fires"],
      ["BOOKED CALL", "She applies for or books a Market Blueprint call", "Aanchal sends a confirmation sequence. Pre-call email sets the emotional frame: 'This isn't a sales call. It's a map.'", "Aanchal manages booking / GHL automation fires confirmation"],
      ["DISCOVERY CALL", "Bethany runs the full call script from Part 1 of this document", "Slow the call. Emotional deep dive. Mirror. Reframe. Paint identity. Soft close. The script is ready.", "Bethany only"],
      ["CLOSED CLIENT", "She enrolls in the 90-Day Growth Engine", "Bethany sends a personal welcome message. Aanchal kicks off onboarding. Eric tracks the close in the pipeline.", "Bethany closes / Eric tracks / Aanchal onboards"],
      ["RETENTION + ASCENSION", "She completes the Growth Engine and is offered the retainer or Luxora Elite", "Bethany personally invites qualified clients into Elite. Southern Social uses her results as a future proof post.", "Bethany invites / Eric manages pipeline"]
    ]),
    sp(80),

    // ══════════════════════════════════════════
    // PART 1: DISCOVERY CALL SCRIPT
