const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

const PURPLE  = "3D1F6E";
const GOLD    = "B8922A";
const ROSE    = "7A3050";
const LIGHT_P = "EDE5F7";
const LIGHT_G = "FDF6E3";
const LIGHT_R = "F9EDF3";
const GRAY    = "F4F4F4";
const WHITE   = "FFFFFF";
const DARK    = "1A1A1A";
const MID     = "555555";

const nb = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: nb, bottom: nb, left: nb, right: nb };
const tb = (c) => ({ style: BorderStyle.SINGLE, size: 1, color: c });

const sp = (n = 40) => new Paragraph({ spacing: { before: n, after: n }, children: [new TextRun("")] });

const div = (c = PURPLE, sz = 6) => new Paragraph({
  spacing: { before: 80, after: 80 },
  border: { bottom: { style: BorderStyle.SINGLE, size: sz, color: c, space: 1 } },
  children: [new TextRun("")]
});

const thin = () => new Paragraph({
  spacing: { before: 30, after: 30 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD", space: 1 } },
  children: [new TextRun("")]
});

const h = (t, size, c, bold = true, align = AlignmentType.LEFT) => new Paragraph({
  alignment: align,
  spacing: { before: 60, after: 40 },
  children: [new TextRun({ text: t, font: "Arial", size, bold, color: c })]
});

const body = (t, bold = false, c = DARK, size = 19) => new Paragraph({
  spacing: { before: 35, after: 35 },
  children: [new TextRun({ text: t, font: "Arial", size, bold, color: c })]
});

const bul = (t, bold = false, c = DARK, indent = 360) => new Paragraph({
  numbering: { reference: "bul", level: 0 },
  spacing: { before: 30, after: 30 },
  children: [new TextRun({ text: t, font: "Arial", size: 19, bold, color: c })]
});

const note = (t) => new Paragraph({
  spacing: { before: 25, after: 25 },
  children: [new TextRun({ text: t, font: "Arial", size: 17, italic: true, color: MID })]
});

const labelLine = (label, text, lc = PURPLE) => new Paragraph({
  spacing: { before: 35, after: 35 },
  children: [
    new TextRun({ text: label + "  ", font: "Arial", size: 19, bold: true, color: lc }),
    new TextRun({ text: text, font: "Arial", size: 19, color: DARK })
  ]
});

const box = (lines, fill, tc = DARK) => new Table({
  width: { size: 9200, type: WidthType.DXA },
  columnWidths: [9200],
  rows: lines.map(l => new TableRow({ children: [new TableCell({
    borders: noBorders,
    width: { size: 9200, type: WidthType.DXA },
    shading: { fill, type: ShadingType.CLEAR },
    margins: { top: 55, bottom: 55, left: 200, right: 200 },
    children: [new Paragraph({
      spacing: { before: l.trim() === "" ? 14 : 36, after: l.trim() === "" ? 14 : 36 },
      children: [new TextRun({
        text: l, font: "Arial",
        size: l.trim() === "" ? 6 : 18,
        color: l.trim() === "" ? fill : tc,
        bold: l.startsWith(">>") || (l.toUpperCase() === l && l.trim().length > 2 && !l.startsWith("("))
      })]
    })]
  })]})
)});

const twoCol = (left, right, lFill, rFill) => new Table({
  width: { size: 9200, type: WidthType.DXA },
  columnWidths: [4540, 4540],
  rows: [new TableRow({ children: [
    new TableCell({
      borders: noBorders, width: { size: 4540, type: WidthType.DXA },
      shading: { fill: lFill, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 180, right: 180 },
      children: left.map(l => new Paragraph({
        spacing: { before: l.trim() === "" ? 10 : 32, after: l.trim() === "" ? 10 : 32 },
        children: [new TextRun({ text: l, font: "Arial", size: 18, color: DARK, bold: l.startsWith("STOP") || l.startsWith("START") })]
      }))
    }),
    new TableCell({
      borders: noBorders, width: { size: 4540, type: WidthType.DXA },
